"Email Services ":" خدمات البريد الإلكتروني ",
"SMTP Service":" خدمة SMTP ",
"Location Settings":" إعدادات الموقع ",
"Risk Assessment":" تقييم المخاطر ",
"Advanced Settings":" الإعدادات المتقدمة ",
"You can use your own SMTP services or use the default service":" يمكنك استخدام خدمات SMTP الخاصة بك أو استخدام الخدمة الافتراضية ",
"  Add Service":" أضف الخدمة ",
"Select Default Provider":" حدد مزود الافتراضي ",
"LeadConnector Email System":" نظام البريد الإلكتروني LeadConnector ",
"  Dedicated domain":" مجال مخصص ",
"Not having a dedicated sending domain can lead to several issues when it comes to email communication. Here are some of the potential problems you may face: ":" يمكن أن يؤدي عدم وجود مجال إرسال مخصص إلى العديد من المشكلات عندما يتعلق الأمر بالاتصال بالبريد الإلكتروني.فيما يلي بعض المشاكل المحتملة التي قد تواجهها: ",
" Messages may be caught in spam filters or rejected by recipients due to suspicions of spam or phishing, as shared or unknown domains lack a positive email reputation.":" قد يتم اكتشاف الرسائل في مرشحات البريد العشوائي أو رفضها من قبل المستلمين بسبب الشكوك في البريد العشوائي أو التصيد ، حيث أن المجالات المشتركة أو غير المعروفة تفتقر إلى سمعة بريد إلكتروني إيجابية. ",
"Deliverability Problems:":" مشاكل التسليم: ",
" If the domain you are using for sending emails is associated with spam or misuse, it can damage its reputation. This could also lead to other legitimate emails from the same domain, like your company's website or other services, being treated as suspicious.":" إذا كان المجال الذي تستخدمه لإرسال رسائل البريد الإلكتروني مرتبطًا بالرسائل غير المرغوب فيها أو إساءة الاستخدام ، فقد يتسبب ذلك في إتلاف سمعته.قد يؤدي ذلك أيضًا إلى رسائل بريد إلكتروني مشروعة أخرى من نفس المجال ، مثل موقع شركتك أو الخدمات الأخرى ، التي يتم التعامل معها على أنها مشبوهة. ",
"Reputation Damage:":" تلف السمعة: ",
" Using a shared domain or a domain you don't control for sending emails means you have limited control over the DNS settings, SPF (Sender Policy Framework), DKIM (DomainKeys Identified Mail), and DMARC (Domain-based Message Authentication, Reporting, and Conformance) records, which are essential for email authentication and deliverability.":" إن استخدام مجال مشترك أو مجال لا تتحكم فيه لإرسال رسائل البريد الإلكتروني يعني أن لديك تحكمًا محدودًا في إعدادات DNS ، و SPF (إطار سياسة المرسل) ، و DKIM (تم تحديد DOMAINKEYS MAIL) ، و DMARC (مصادقة الرسائل المستندة إلى المجال ، والإبلاغ ،والتوافق) السجلات ، والتي تعتبر ضرورية لمصادقة البريد الإلكتروني وقابليتها للتسليم. ",
"Limited Control:":" سيطرة محدودة: ",
" A dedicated sending domain allows you to align your email communications with your brand. Without it, your emails may appear less trustworthy or less professional, as the sender's address won't match your company's domain.":" يتيح لك مجال إرسال مخصص مواءمة اتصالات البريد الإلكتروني الخاصة بك مع علامتك التجارية.بدون ذلك ، قد تبدو رسائل البريد الإلكتروني الخاصة بك أقل جدارة بالثقة أو أقل احترافية ، لأن عنوان المرسل لن يتطابق مع مجال شركتك. ",
"Branding Issues:":" قضايا العلامات التجارية: ",
"Important Notification: Boost Your Email Deliverability!":" إشعار مهم: تعزيز إمكانية تسليم البريد الإلكتروني الخاص بك! ",
"Dedicated Sending Domain for Improved Email Delivery":" مجال إرسال مخصص لتحسين تسليم البريد الإلكتروني ",
"Currently you are using a shared sending domain for your email communications. While this is a convenient option, we would like to recommend a strategic enhancement to your email delivery process - creating your very own dedicated sending domain.":" أنت تستخدم حاليًا مجال إرسال مشترك للاتصالات عبر البريد الإلكتروني.على الرغم من أن هذا خيار مناسب ، إلا أننا نود أن نوصي بالتحسين الاستراتيجي لعملية تسليم البريد الإلكتروني الخاصة بك - إنشاء مجال إرسال مخصص خاص بك. ",
"Why should you consider this upgrade?":" لماذا يجب أن تفكر في هذه الترقية؟ ",
"With a dedicated sending domain, your emails are less likely to be affected by the reputation of other senders sharing the same domain. This means your important messages will have a better chance of reaching your recipients' inboxes":" من خلال مجال إرسال مخصص ، من غير المرجح أن تتأثر رسائل البريد الإلكتروني الخاصة بك بسمعة المرسلين الآخرين الذين يشاركون نفس المجال.هذا يعني أن رسائلك المهمة سيكون لها فرصة أفضل للوصول إلى صناديق الوارد الخاصة بك للمستفيدين ",
"Enhanced Deliverability: ":" قابلية التسليم المعززة: ",
"A dedicated sending domain adds a professional touch to your emails, reinforcing your brand identity and building trust with your recipients.":" يضيف مجال إرسال مخصص لمسة احترافية إلى رسائل البريد الإلكتروني الخاصة بك ، وتعزيز هوية علامتك التجارية وبناء الثقة مع المستلمين. ",
"Brand Credibility: ":" مصداقية العلامة التجارية: ",
"Managing your own sending domain gives you greater control over your email deliverability, allowing you to set up authentication protocols like SPF, DKIM, and DMARC to prevent unauthorized use of your domain.":" تمنحك إدارة مجال الإرسال الخاص بك تحكمًا أكبر في إمكانية تسليم بريدك الإلكتروني ، مما يتيح لك إعداد بروتوكولات المصادقة مثل SPF و DKIM و DMARC لمنع الاستخدام غير المصرح به لمجالك. ",
"Increased Control: ":" زيادة السيطرة: ",
"Shared domains can sometimes lead to higher spam-flagging rates. By transitioning to your own sending domain, you reduce the risk of your legitimate emails being mistaken for spam.":" يمكن أن تؤدي المجالات المشتركة في بعض الأحيان إلى ارتفاع معدلات تراجع البريد العشوائي.عن طريق الانتقال إلى مجال الإرسال الخاص بك ، فإنك تقلل من خطر أن تخطئ رسائل البريد الإلكتروني المشروعة في البريد العشوائي. ",
"Reduced Spam Flagging: ":" انخفاض علامة البريد العشوائي: ",
"Create Dedicated Domain":" إنشاء مجال مخصص ",
"Email Settings for Locations":" إعدادات البريد الإلكتروني للمواقع ",
"You can set your own MailGun domain or LeadConnector domain.":" يمكنك تعيين مجال MailGun الخاص بك أو مجال LeadConnector. ",
"Enable Email Verification for all sub-accounts":" تمكين التحقق من البريد الإلكتروني لجميع الحسابات الفرعية ",
